#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    int n = strtol(argv[1], NULL, 10);
    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }

    long long triangle[n][n];
    for (int i = 0; i < n; i++) {
        triangle[i][0] = 1;
        triangle[i][i] = 1;
    }

    for (int i = 2; i < n; i++) {
        for (int j = 1; j < i; j++) {
            triangle[i][j] = triangle[i-1][j-1] + triangle[i-1][j];
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            putchar(' ');
        }
        for (int j = 0; j <= i; j++) {
            printf("%lld ", triangle[i][j]);
        }
        putchar('\n');
    }

    return 0;
}
